package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService defines the interface for user-related operations
type UserService interface {
	GetAllUsers() []User
	CreateUser(user User) (User, error)
	GetUserByID(id string) (User, error)
}

// inMemoryUserService implements UserService using an in-memory map
type inMemoryUserService struct {
	users map[string]User
	mutex sync.RWMutex
}

// NewInMemoryUserService creates a new instance of inMemoryUserService
func NewInMemoryUserService() UserService {
	return &inMemoryUserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns all users
func (s *inMemoryUserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and assigns a UUID
func (s *inMemoryUserService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

// GetUserByID returns a user by ID
func (s *inMemoryUserService) GetUserByID(id string) (User, error) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	if !ok {
		return User{}, fmt.Errorf("user with ID %s not found", id)
	}
	return u, nil
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"legacy_refactor/internal/service"
)

// UserHandlers provides HTTP handlers for user-related operations
type UserHandlers struct {
	service service.UserService
}

// NewUserHandlers creates a new instance of UserHandlers
func NewUserHandlers(s service.UserService) *UserHandlers {
	return &UserHandlers{service: s}
}

// RegisterRoutes registers the user API routes
func (h *UserHandlers) RegisterRoutes() {
	http.HandleFunc("/users", h.usersHandler)
	http.HandleFunc("/users/", h.userByIDHandler)
}

func (h *UserHandlers) usersHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.getAllUsers(w, r)
	case http.MethodPost:
		h.createUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) userByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	if id == "" {
		http.NotFound(w, r)
		return
	}

	switch r.Method {
	case http.MethodGet:
		h.getUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (h *UserHandlers) getAllUsers(w http.ResponseWriter, r *http.Request) {
	users := h.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

func (h *UserHandlers) createUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.service.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

func (h *UserHandlers) getUserByID(w http.ResponseWriter, r *http.Request, id string) {
	user, err := h.service.GetUserByID(id)
	if err != nil {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"legacy_refactor/internal/api"
	"legacy_refactor/internal/service"
)

func main() {
	// Initialize service
	userService := service.NewInMemoryUserService()

	// Initialize handlers with the service
	handlers := api.NewUserHandlers(userService)

	// Register routes
	handlers.RegisterRoutes()

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestInMemoryUserService_CreateUser(t *testing.T) {
	service := NewInMemoryUserService()

	user := User{Name: "Test User", Email: "test@example.com"}
	createdUser, err := service.CreateUser(user)

	assert.NoError(t, err)
	assert.NotEmpty(t, createdUser.ID)
	assert.Equal(t, user.Name, createdUser.Name)
	assert.Equal(t, user.Email, createdUser.Email)

	// Verify the user is in the storage
	retrievedUser, err := service.GetUserByID(createdUser.ID)
	assert.NoError(t, err)
	assert.Equal(t, createdUser, retrievedUser)
}

func TestInMemoryUserService_GetAllUsers(t *testing.T) {
	service := NewInMemoryUserService()

	user1 := User{Name: "User 1", Email: "user1@example.com"}
	user2 := User{Name: "User 2", Email: "user2@example.com"}

	service.CreateUser(user1)
	service.CreateUser(user2)

	users := service.GetAllUsers()
	assert.Len(t, users, 2)

	// Check if both users are present (order doesn't matter for GetAll)
	found1 := false
	found2 := false
	for _, u := range users {
		if u.Name == user1.Name {
			found1 = true
		}
		if u.Name == user2.Name {
			found2 = true
		}
	}
	assert.True(t, found1)
	assert.True(t, found2)
}

func TestInMemoryUserService_GetUserByID(t *testing.T) {
	service := NewInMemoryUserService()

	user := User{Name: "Single User", Email: "single@example.com"}
	createdUser, _ := service.CreateUser(user)

	retrievedUser, err := service.GetUserByID(createdUser.ID)
	assert.NoError(t, err)
	assert.Equal(t, createdUser, retrievedUser)

	// Test non-existent user
	_, err = service.GetUserByID("non-existent-id")
	assert.Error(t, err)
	assert.Contains(t, err.Error(), "not found")
}
